import React, { useState, useEffect, useCallback } from 'react';
import { useAuth } from '../AuthContext';
import IntelFeed from './IntelFeed';

function MemberDashboard() {
  const { authFetch } = useAuth();
  const [intels, setIntels] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');
  const [selectedIntel, setSelectedIntel] = useState(null);

  // Form states
  const [findings, setFindings] = useState('');
  const [assets, setAssets] = useState('');
  const [mitigations, setMitigations] = useState('');
  
  // Alert form states
  const [ciiSector, setCiiSector] = useState('Aviation');
  const [sectorLeadName, setSectorLeadName] = useState('Statutory Board');
  const [affectedMemberStatus, setAffectedMemberStatus] = useState('No');
  const [affectedEnvironment, setAffectedEnvironment] = useState('CII');
  const [delayReason, setDelayReason] = useState('Pending patch testing');
  const todayStr = new Date().toISOString().split('T')[0];
  const [expectedVerificationDate, setExpectedVerificationDate] = useState(todayStr);
  const [patchStatus, setPatchStatus] = useState('Completed');
  const [mitigationMeasureIfNotPatched, setMitigationMeasureIfNotPatched] = useState('Protection Controls');
  const [iocTrafficDirection, setIocTrafficDirection] = useState('Inbound');
  const [followUpAction, setFollowUpAction] = useState('IOC Blocked');
  const [otherTypeOfAlert, setOtherTypeOfAlert] = useState('NIL');

  const [evidenceFiles, setEvidenceFiles] = useState([]);
  const [editingResponseId, setEditingResponseId] = useState(null);

  const fetchIntels = useCallback(async () => {
    setLoading(true);
    try {
      const res = await authFetch('/api/v1/intel/member');
      if (res.ok) {
        const data = await res.json();
        if (filter !== 'all') {
          setIntels(data.filter(i => i.type === filter));
        } else {
          setIntels(data);
        }
        
        // Update selected intel reference if it exists without depending on selectedIntel
        setSelectedIntel(prev => {
          if (prev) {
            return data.find(i => i.id === prev.id) || prev;
          }
          return prev;
        });
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  }, [authFetch, filter]);

  useEffect(() => {
    fetchIntels();
  }, [fetchIntels]);

  const handleAcknowledge = async () => {
    if (!selectedIntel) return;
    try {
      await authFetch(`/api/v1/intel/${selectedIntel.id}/acknowledge`, { method: 'POST' });
      fetchIntels();
    } catch (err) {
      console.error(err);
    }
  };

  const handleStartEdit = (resp) => {
    setEditingResponseId(resp.id);
    if (selectedIntel.type === 'Alert') {
      setCiiSector(resp.cii_sector || 'Aviation');
      setSectorLeadName(resp.sector_lead_name || 'Statutory Board');
      setAffectedMemberStatus(resp.affected_member_status || 'No');
      setAffectedEnvironment(resp.affected_environment || 'CII');
      setDelayReason(resp.delay_reason || '');
      setExpectedVerificationDate(resp.expected_verification_date ? resp.expected_verification_date.split('T')[0] : todayStr);
      setPatchStatus(resp.patch_status || 'Completed');
      setMitigationMeasureIfNotPatched(resp.mitigation_measure_if_not_patched || 'Protection Controls');
      setIocTrafficDirection(resp.ioc_traffic_direction || 'Inbound');
      setFollowUpAction(resp.follow_up_action || 'IOC Blocked');
      setOtherTypeOfAlert(resp.other_type_of_alert || 'NIL');
    } else {
      setFindings(resp.findings || '');
      setAssets(resp.affected_assets ? resp.affected_assets.join(', ') : '');
      setMitigations(resp.mitigation_measures ? resp.mitigation_measures.join('\n') : '');
    }
  };

  const handleCancelEdit = () => {
    setEditingResponseId(null);
    setFindings('');
    setAssets('');
    setMitigations('');
    setCiiSector('Aviation');
    setSectorLeadName('Statutory Board');
    setAffectedMemberStatus('No');
    setAffectedEnvironment('CII');
    setDelayReason('Pending patch testing');
    setExpectedVerificationDate(todayStr);
    setPatchStatus('Completed');
    setMitigationMeasureIfNotPatched('Protection Controls');
    setIocTrafficDirection('Inbound');
    setFollowUpAction('IOC Blocked');
    setOtherTypeOfAlert('NIL');
    setEvidenceFiles([]);
  };

  const handleSubmitResponse = async (e) => {
    e.preventDefault();
    if (!selectedIntel) return;
    
    let payload = {};
    if (selectedIntel.type === 'Alert') {
      payload = {
        cii_sector: ciiSector,
        sector_lead_name: sectorLeadName,
        affected_member_status: affectedMemberStatus,
        affected_environment: affectedEnvironment,
        delay_reason: delayReason,
        expected_verification_date: expectedVerificationDate || null,
        patch_status: patchStatus,
        mitigation_measure_if_not_patched: mitigationMeasureIfNotPatched,
        ioc_traffic_direction: iocTrafficDirection,
        follow_up_action: followUpAction,
        other_type_of_alert: otherTypeOfAlert
      };
    } else {
      payload = {
        findings,
        affected_assets: assets.split(',').map(s => s.trim()).filter(Boolean),
        mitigation_measures: mitigations.split('\n').map(s => s.trim()).filter(Boolean),
      };
    }

    try {
      const url = editingResponseId
        ? `/api/v1/intel/${selectedIntel.id}/responses/${editingResponseId}`
        : `/api/v1/intel/${selectedIntel.id}/respond`;
      const method = editingResponseId ? 'PUT' : 'POST';

      const res = await authFetch(url, { 
        method,
        body: JSON.stringify(payload)
      });
      
      const resData = await res.json();
      const targetResponseId = resData.response_id;
      
      if (targetResponseId && evidenceFiles.length > 0) {
        const formData = new FormData();
        evidenceFiles.forEach(file => {
          formData.append('files', file);
        });
        await authFetch(`/api/v1/intel/${selectedIntel.id}/responses/${targetResponseId}/evidence`, {
          method: 'POST',
          body: formData,
          omitContentType: true
        });
      }
      
      handleCancelEdit();
      fetchIntels();
    } catch (err) {
      console.error(err);
    }
  };
  

  const handleDownload = async (e, url, filename) => {
    e.preventDefault();
    try {
      const res = await authFetch(url);
      if (!res.ok) throw new Error('Download failed');
      const blob = await res.blob();
      const objectUrl = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = objectUrl;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      a.remove();
      window.URL.revokeObjectURL(objectUrl);
    } catch (err) {
      console.error(err);
      alert('Failed to download file.');
    }
  };

  return (
    <div className="main-content">
      <div style={{ display: 'flex', flexDirection: 'column', flex: 1, overflow: 'hidden' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '15px 25px', borderBottom: '1px solid var(--border-color)', backgroundColor: 'var(--bg-glass)', gap: '10px' }}>
          <div style={{ fontWeight: '600', fontSize: '18px' }}>Member Dashboard</div>
          <div style={{ display: 'flex', gap: '10px' }}>
            <button className="submit-btn" onClick={(e) => handleDownload(e, '/api/v1/intel/export/csv', 'my_intel_report.csv')} style={{ padding: '8px 16px', fontSize: '14px', backgroundColor: 'transparent', border: '1px solid var(--border-color)' }}>
              Export CSV
            </button>
          </div>
        </div>
        <IntelFeed 
          intels={intels} 
          loading={loading} 
          filter={filter} 
          onFilterChange={setFilter} 
          onIntelSelect={(item) => {
            setSelectedIntel(item);
            setEditingResponseId(null);
          }}
        />
      </div>

      <div className="form-panel" style={{ overflowY: 'auto' }}>
        <div className="form-panel-header">
          <div className="form-panel-title">Investigation & Response</div>
        </div>

        {!selectedIntel ? (
          <div className="feed-empty">
            <div className="feed-empty-title">Select an Alert</div>
            <div className="feed-empty-sub">Click an alert on the left to acknowledge and respond.</div>
          </div>
        ) : (
          <div style={{ padding: '20px' }}>
            <h3 style={{ marginBottom: '10px' }}>{selectedIntel.title}</h3>
            
            <div style={{ marginBottom: '20px', padding: '10px', background: 'var(--bg-glass)', borderRadius: 'var(--radius-sm)' }}>
              <div style={{ fontSize: '11px', color: 'var(--text-dim)', marginBottom: '5px' }}>My Status:</div>
              <div style={{ fontWeight: 'bold', color: selectedIntel.my_status.status === 'UNACKNOWLEDGED' ? 'var(--alert-color)' : 'var(--accent)' }}>
                {selectedIntel.my_status.status}
              </div>
              
              {selectedIntel.my_status.status === 'UNACKNOWLEDGED' && (
                <button className="submit-btn" style={{ marginTop: '10px' }} onClick={handleAcknowledge}>
                  Acknowledge Receipt
                </button>
              )}
              {(selectedIntel.my_status.status === 'RESPONDED' || selectedIntel.my_status.status === 'UPDATED') && !editingResponseId && (
                <button
                  type="button"
                  className="submit-btn"
                  style={{ marginTop: '10px', background: 'transparent', border: '1px solid var(--accent)', color: 'var(--accent)' }}
                  onClick={() => {
                    const latestResp = selectedIntel.my_responses?.[selectedIntel.my_responses.length - 1];
                    if (latestResp) {
                      handleStartEdit(latestResp);
                    }
                  }}
                >
                  Edit / Update Response
                </button>
              )}
            </div>

            {(editingResponseId !== null || (selectedIntel.my_status.status !== 'UNACKNOWLEDGED' && selectedIntel.my_status.status !== 'RESPONDED' && selectedIntel.my_status.status !== 'UPDATED')) ? (
              <form onSubmit={handleSubmitResponse} style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
                {selectedIntel.type === 'Alert' ? (
                  <>
                    <div className="form-section-label" style={{ marginTop: '10px' }}>Section A: General Information</div>
                    <div className="field-group">
                      <label className="field-label">CII Sector</label>
                      <select className="field-input" value={ciiSector} onChange={e => setCiiSector(e.target.value)}>
                        {['Aviation', 'Banking and Finance', 'Energy', 'Government', 'Healthcare', 'Infocomm', 'Land Transport', 'Maritime', 'Media', 'Security and Emergency Services', 'Water'].map(s => <option key={s} value={s}>{s}</option>)}
                      </select>
                    </div>
                    <div className="field-group">
                      <label className="field-label">Sector Lead Name</label>
                      <input className="field-input" value={sectorLeadName} onChange={e => setSectorLeadName(e.target.value)} />
                    </div>

                    <div className="form-section-label" style={{ marginTop: '10px' }}>Section B: Checking of Affected Products</div>
                    <div className="field-group">
                      <label className="field-label">Are there any CIIOs in your sector that are affected?</label>
                      <select className="field-input" value={affectedMemberStatus} onChange={e => setAffectedMemberStatus(e.target.value)}>
                        <option value="Yes">Yes</option>
                        <option value="No">No</option>
                        <option value="Pending Response">Pending Response</option>
                      </select>
                    </div>
                    <div className="field-group">
                      <label className="field-label">Affected Environment</label>
                      <select className="field-input" value={affectedEnvironment} onChange={e => setAffectedEnvironment(e.target.value)}>
                        <option value="CII">CII</option>
                        <option value="Non-CII">Non-CII</option>
                      </select>
                    </div>
                    <div className="field-group">
                      <label className="field-label">Reason for not meeting deadline or yet to response</label>
                      <textarea className="field-textarea" value={delayReason} onChange={e => setDelayReason(e.target.value)} />
                    </div>
                    <div className="field-group">
                      <label className="field-label">Expected product verification date / response date</label>
                      <input type="date" className="field-input" value={expectedVerificationDate} onChange={e => setExpectedVerificationDate(e.target.value)} />
                    </div>

                    <div className="form-section-label" style={{ marginTop: '10px' }}>Section C: Patching of Affected Products</div>
                    <div className="field-group">
                      <label className="field-label">Patch Status</label>
                      <select className="field-input" value={patchStatus} onChange={e => setPatchStatus(e.target.value)}>
                        {['Completed', 'In Progress', 'Replacing Affected Product Through Tech Refresh', 'Pending'].map(s => <option key={s} value={s}>{s}</option>)}
                      </select>
                    </div>
                    <div className="field-group">
                      <label className="field-label">If patching not completed, provide mitigation measure</label>
                      <textarea className="field-textarea" value={mitigationMeasureIfNotPatched} onChange={e => setMitigationMeasureIfNotPatched(e.target.value)} />
                    </div>

                    <div className="form-section-label" style={{ marginTop: '10px' }}>Section D: IOC Scan Results</div>
                    <div className="field-group">
                      <label className="field-label">Is the IOC traffic inbound, outbound or both?</label>
                      <select className="field-input" value={iocTrafficDirection} onChange={e => setIocTrafficDirection(e.target.value)}>
                        <option value="Inbound">Inbound</option>
                        <option value="Outbound">Outbound</option>
                        <option value="Both">Both</option>
                      </select>
                    </div>
                    <div className="field-group">
                      <label className="field-label">Follow up action(s) taken and results of impact assessment?</label>
                      <textarea className="field-textarea" value={followUpAction} onChange={e => setFollowUpAction(e.target.value)} />
                    </div>

                    <div className="form-section-label" style={{ marginTop: '10px' }}>Section E: Others</div>
                    <div className="field-group">
                      <label className="field-label">Alerts which require action but not covered by other sections</label>
                      <textarea className="field-textarea" value={otherTypeOfAlert} onChange={e => setOtherTypeOfAlert(e.target.value)} />
                    </div>
                  </>
                ) : (
                  <>
                    <div className="form-section-label">
                      Submit Investigation
                    </div>
                    
                    <div className="field-group">
                      <label className="field-label">Findings <span className="field-required">*</span></label>
                      <textarea 
                        className="field-textarea" 
                        value={findings} 
                        onChange={e => setFindings(e.target.value)} 
                        required 
                        placeholder="Results of your internal investigation..."
                      />
                    </div>

                    <div className="field-group">
                      <label className="field-label">Affected Assets (comma separated)</label>
                      <input 
                        className="field-input" 
                        value={assets} 
                        onChange={e => setAssets(e.target.value)} 
                        placeholder="e.g. server-01, DB-master"
                      />
                    </div>

                    <div className="field-group">
                      <label className="field-label">Mitigation Measures (one per line)</label>
                      <textarea 
                        className="field-textarea" 
                        value={mitigations} 
                        onChange={e => setMitigations(e.target.value)} 
                        placeholder="e.g. Patched to 14.2"
                      />
                    </div>
                  </>
                )}

                <div className="form-section-label" style={{ marginTop: '10px' }}>{selectedIntel.type === 'Alert' ? 'Section F: Attachment' : ''}</div>
                <div className="field-group">
                  <label className="field-label">Supporting Evidence (multiple files allowed)</label>
                  <input 
                    type="file" 
                    multiple
                    className="field-input" 
                    style={{ padding: '5px' }}
                    onChange={e => setEvidenceFiles(Array.from(e.target.files))} 
                  />
                </div>

                <div style={{ display: 'flex', gap: '10px', marginTop: '10px' }}>
                  <button type="submit" className="submit-btn" style={{ flex: 1 }}>
                    {editingResponseId ? 'Update Response' : 'Submit Response'}
                  </button>
                  {editingResponseId && (
                    <button
                      type="button"
                      className="submit-btn"
                      style={{ flex: 1, background: 'var(--bg-glass)', border: '1px solid var(--text-dim)' }}
                      onClick={handleCancelEdit}
                    >
                      Cancel Edit
                    </button>
                  )}
                </div>
              </form>
            ) : null}
            
            {selectedIntel.my_responses?.length > 0 && (
              <div style={{ marginTop: '20px' }}>
                <div className="form-section-label">Past Responses</div>
                {selectedIntel.my_responses.map(resp => (
                  <div key={resp.id} style={{ padding: '10px', background: 'rgba(0,0,0,0.2)', borderRadius: '4px', marginTop: '10px' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                      <div style={{ fontSize: '11px' }}>
                        <div style={{ marginBottom: '5px' }}>
                          <strong>SLA Compliance: </strong> 
                          {resp.sla_met === true && <span style={{ color: 'var(--accent)', fontWeight: 'bold' }}>Yes</span>}
                          {resp.sla_met === false && <span style={{ color: 'var(--alert-color)', fontWeight: 'bold' }}>No</span>}
                          {resp.sla_met === null && <span style={{ color: 'var(--text-dim)' }}>N/A</span>}
                        </div>
                        {selectedIntel.type === 'Alert' ? (
                          <div style={{ display: 'flex', flexDirection: 'column', gap: '4px', marginTop: '5px' }}>
                            <div><strong>CII Sector:</strong> {resp.cii_sector}</div>
                            <div><strong>Sector Lead:</strong> {resp.sector_lead_name}</div>
                            <div><strong>Affected CIIOs:</strong> {resp.affected_member_status}</div>
                            <div><strong>Environment:</strong> {resp.affected_environment}</div>
                            <div><strong>Delay Reason:</strong> {resp.delay_reason || 'N/A'}</div>
                            <div><strong>Expected Date:</strong> {resp.expected_verification_date || 'N/A'}</div>
                            <div><strong>Patch Status:</strong> {resp.patch_status}</div>
                            <div><strong>Mitigation Measure:</strong> {resp.mitigation_measure_if_not_patched || 'N/A'}</div>
                            <div><strong>IOC Direction:</strong> {resp.ioc_traffic_direction}</div>
                            <div><strong>Follow-up Action:</strong> {resp.follow_up_action || 'N/A'}</div>
                            <div><strong>Others:</strong> {resp.other_type_of_alert || 'N/A'}</div>
                          </div>
                        ) : (
                          <>
                            <strong>Findings:</strong> {resp.findings}
                          </>
                        )}
                      </div>
                      <button
                        type="button"
                        className="submit-btn"
                        style={{ padding: '4px 10px', fontSize: '11px', background: 'transparent', border: '1px solid var(--accent)', color: 'var(--accent)', marginLeft: '10px' }}
                        onClick={() => handleStartEdit(resp)}
                      >
                        Edit
                      </button>
                    </div>
                    {selectedIntel.type !== 'Alert' && resp.affected_assets && resp.affected_assets.length > 0 && (
                      <div style={{ fontSize: '11px', marginTop: '5px' }}><strong>Affected Assets:</strong> {resp.affected_assets.join(', ')}</div>
                    )}
                    {selectedIntel.type !== 'Alert' && resp.mitigation_measures && resp.mitigation_measures.length > 0 && (
                      <div style={{ fontSize: '11px', marginTop: '5px' }}><strong>Mitigation Measures:</strong> {resp.mitigation_measures.join(', ')}</div>
                    )}
                    {resp.evidence_files && resp.evidence_files.length > 0 && (
                      <div style={{ marginTop: '10px' }}>
                        <div style={{ fontSize: '11px', marginBottom: '5px' }}><strong>Supporting Evidence:</strong></div>
                        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '5px' }}>
                          {resp.evidence_files.map((file, idx) => (
                            <a
                              key={idx}
                              href="#"
                              onClick={(e) => handleDownload(e, `/api/v1/intel/${selectedIntel.id}/responses/${resp.id}/evidence/${encodeURIComponent(file.filename)}`, file.filename)}
                              className="attachment-pill"
                            >
                              📄 {file.filename}
                            </a>
                          ))}
                        </div>
                      </div>
                    )}
                    <div style={{ fontSize: '11px', marginTop: '5px' }}><strong>Review Status:</strong> {resp.review_status}</div>
                    {resp.reviewer_comments && (
                      <div style={{ fontSize: '11px', marginTop: '5px', color: 'var(--alert-color)' }}>
                        <strong>ACSAC Feedback:</strong> {resp.reviewer_comments}
                      </div>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

export default MemberDashboard;
